def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]
    if denominator == 0:
        return None
    portion = round(numerator / denominator, 3)
    return {
        "value": portion,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "portion": portion,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
